mapper.select:
select count(*) from biz_project_blacklist
where target_type = #{targetType} and target_id = #{targetId}
  and (
    (kind = 'ip' and #{ip} is not null and #{ip} <> '' and value = #{ip})
    or (kind = 'device' and #{device} is not null and #{device} <> '' and value = #{device})
  )
